const src = ($json.body && typeof $json.body === 'object') ? $json.body : $json;
const clean = (v) => (v === undefined || v === null) ? '' : String(v).trim();
const reporter_name = clean(src.reporter_name);
const reporter_email = clean(src.reporter_email).toLowerCase();
const description = clean(src.description);
const emailRe = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

let error = '';
if (!description) error = 'Please describe the incident.';
else if (description.length < 10) error = 'The description is too short (minimum 10 characters).';
else if (description.length > 2000) error = 'The description is too long (maximum 2000 characters).';
else if (!reporter_name) error = 'Please enter your name.';
else if (reporter_name.length > 100) error = 'Your name is too long (maximum 100 characters).';
else if (!emailRe.test(reporter_email) || reporter_email.length > 254) error = 'Please enter a valid email address.';

return { json: { valid: error === '', error, reporter_name, reporter_email, description } };

const ALLOWED = ['Phishing', 'Lost or Stolen Device', 'Malware Suspected', 'Account Compromise', 'Other'];
const input = $('Validate Input').item.json;

let incident_type = 'Other';
let reason = 'AI output could not be verified';
let needs_review = 'YES';

try {
  let raw = $json.output;
  let parsed = null;
  if (raw && typeof raw === 'object') {
    parsed = raw;
  } else if (typeof raw === 'string') {
    const start = raw.indexOf('{');
    const end = raw.lastIndexOf('}');
    if (start !== -1 && end > start) parsed = JSON.parse(raw.slice(start, end + 1));
  }
  if (parsed && typeof parsed.incident_type === 'string' && ALLOWED.includes(parsed.incident_type)) {
    incident_type = parsed.incident_type;
    const r = typeof parsed.reason === 'string' ? parsed.reason.trim() : '';
    reason = r ? r.slice(0, 300) : 'No reason provided';
    needs_review = 'NO';
  }
} catch (e) {
  // keep safe defaults
}

const incident_id = 'INC-' + String(Date.now()).slice(-7) + String(Math.floor(Math.random() * 90) + 10);

return { json: {
  incident_id,
  timestamp: new Date().toISOString(),
  reporter_name: input.reporter_name,
  reporter_email: input.reporter_email,
  description: input.description,
  incident_type,
  ai_reason: reason,
  needs_review,
} };

const incident = $('Review AI Output').first().json;
const rows = $input.all()
  .map(i => i.json || {})
  .filter(r => r && typeof r.incident_type === 'string' && !r.error);

const norm = (s) => String(s || '').trim().toLowerCase();
const match = rows.find(r => norm(r.incident_type) === norm(incident.incident_type));
const fallback = rows.find(r => norm(r.incident_type) === 'other');
const row = match || fallback;

// Static safety net only if the sheet itself is unreachable (never AI-written).
const STATIC_REPORTER = 'Do not try to fix the issue yourself.\nDisconnect the affected device from the network if it is safe to do so.\nWait for the security team to contact you.';
const STATIC_TEAM = 'Playbook could not be loaded from the sheet. Triage manually and contact the reporter.';

const reporter_steps = row && String(row.reporter_steps || '').trim() ? String(row.reporter_steps) : STATIC_REPORTER;
const team_steps = row && String(row.team_steps || '').trim() ? String(row.team_steps) : STATIC_TEAM;
const playbook_source = match ? 'matched' : (fallback ? 'fallback_other' : 'static_default');

const d = String(incident.description || '');
const short_description = d.length > 300 ? d.slice(0, 297) + '...' : d;

return [{ json: { ...incident, reporter_steps, team_steps, playbook_source, short_description } }];

