const esc = (v) => String(v === undefined || v === null ? '' : v)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&#39;');

const style = '<style>body{margin:0;min-height:100vh;display:flex;align-items:center;justify-content:center;' +
  'font-family:Segoe UI,Roboto,Arial,sans-serif;color:#fff;background:radial-gradient(ellipse at 50% 35%,#08408a 0%,#062a66 55%,#041d4a 100%);}' +
  '.wrap{max-width:640px;width:100%;margin:24px;}' +
  '.card{padding:28px 32px;margin-bottom:18px;border-radius:22px;background:rgba(255,255,255,0.12);' +
  'border:1px solid rgba(255,255,255,0.26);backdrop-filter:blur(14px);-webkit-backdrop-filter:blur(14px);box-shadow:0 20px 50px rgba(0,25,80,0.35);}' +
  'h1{margin:0 0 8px;font-size:24px}h2{margin:0 0 12px;font-size:18px;color:#cfe4ff}' +
  '.label{font-size:12px;letter-spacing:.08em;text-transform:uppercase;color:#9cc7ff}' +
  '.value{font-size:20px;font-weight:600;margin:4px 0 14px}' +
  'ol{margin:0;padding-left:22px}li{margin:8px 0;line-height:1.55}' +
  '.note{padding:12px 16px;border-radius:12px;background:rgba(34,197,94,0.15);border:1px solid rgba(34,197,94,0.4)}</style>';

const page = (body) => '<!DOCTYPE html><html lang="en" dir="ltr"><head><meta charset="utf-8">' +
  '<meta name="viewport" content="width=device-width, initial-scale=1"><title>Incident report received</title>' +
  style + '</head><body><div class="wrap">' + body + '</div></body></html>';

let html;
try {
  const p = $('Resolve Playbook').first().json;
  const steps = String(p.reporter_steps || '')
    .split(/\r?\n/)
    .map(s => s.replace(/^\s*(\d+[.)]|[-*])\s*/, '').trim())
    .filter(Boolean);
  const list = steps.map(s => '<li>' + esc(s) + '</li>').join('');
  html = page(
    '<div class="card"><h1>Incident report received</h1>' +
    '<div class="label">Incident ID</div><div class="value">' + esc(p.incident_id) + '</div>' +
    '<div class="label">Detected type</div><div class="value">' + esc(p.incident_type) + '</div></div>' +
    '<div class="card"><h2>What to do now</h2><ol>' + list + '</ol></div>' +
    '<div class="card note">The security team has been notified.</div>'
  );
} catch (e) {
  html = page(
    '<div class="card"><h1>Incident report received</h1>' +
    '<p>Your report was received, but we could not display the next steps right now.</p>' +
    '<p>Please do not try to fix the issue yourself and contact the security team directly.</p></div>'
  );
}
return [{ json: { html } }];

const esc = (v) => String(v === undefined || v === null ? '' : v)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const msg = esc($json.error || 'The report could not be accepted.');
const html = '<!DOCTYPE html><html lang="en" dir="ltr"><head><meta charset="utf-8">' +
  '<meta name="viewport" content="width=device-width, initial-scale=1"><title>Report not submitted</title>' +
  '<style>body{margin:0;min-height:100vh;display:flex;align-items:center;justify-content:center;' +
  'font-family:Segoe UI,Roboto,Arial,sans-serif;color:#fff;background:linear-gradient(135deg,#1a0b2e 0%,#3b1466 50%,#5b21b6 100%);}' +
  '.card{max-width:560px;margin:24px;padding:32px;border-radius:20px;background:rgba(255,255,255,0.08);' +
  'border:1px solid rgba(255,255,255,0.18);backdrop-filter:blur(14px);-webkit-backdrop-filter:blur(14px);box-shadow:0 8px 32px rgba(0,0,0,0.35);}' +
  'h1{margin-top:0;font-size:24px}p{line-height:1.6;color:#e9defc}.err{padding:12px 16px;border-radius:12px;background:rgba(239,68,68,0.18);border:1px solid rgba(239,68,68,0.45)}</style>' +
  '</head><body><div class="card"><h1>Your report was not submitted</h1>' +
  '<p class="err">' + msg + '</p><p>Please go back, correct the form and submit again. ' +
  'If this is urgent, contact the security team directly.</p></div></body></html>';
return { json: { html } };
